window.addEventListener('load',async()=>{try{await document.fonts.ready;const pages=document.getElementById('reportPages');let content;
function page(){const sheet=document.createElement('section');sheet.className='report-page';sheet.innerHTML='<img class="report-letterhead" src="/timbrado-cabecalho.png" alt="Governo de Araquari"><div class="report-content"></div><footer class="report-footer"><img src="/timbrado-rodape.png" alt="CEI Lindolpho José da Silva — Secretaria de Educação"></footer><div class="report-page-number"></div>';pages.append(sheet);content=sheet.querySelector('.report-content')}
function fits(){return content.scrollHeight<=content.clientHeight+1}
function slice(node,start,end){const clone=node.cloneNode(false);const walker=document.createTreeWalker(node,NodeFilter.SHOW_TEXT);let offset=0,begin=null,finish=null;while(walker.nextNode()){const t=walker.currentNode,len=t.textContent.length;if(begin===null&&start<=offset+len)begin=[t,Math.max(0,start-offset)];if(end<=offset+len){finish=[t,Math.max(0,end-offset)];break}offset+=len}if(!begin||!finish)return clone;const range=document.createRange();range.setStart(...begin);range.setEnd(...finish);clone.append(range.cloneContents());return clone}
function put(node){content.append(node);if(fits())return;node.remove();if(node.matches('.report-signature-row,.report-identification,.report-date,h1,h2,h3,h4,h5,h6')){if(content.children.length)page();content.append(node);if(fits())return;node.remove()}
if(node.matches('ul,ol')){let index=Number(node.getAttribute('start')||1);for(const item of Array.from(node.children)){const list=node.cloneNode(false);if(node.matches('ol'))list.setAttribute('start',index++);list.append(item.cloneNode(true));putListItem(list)}return}
const text=node.textContent;if(!text.length)return;let start=0;while(start<text.length){let low=start+1,high=text.length,best=start;while(low<=high){const mid=Math.floor((low+high)/2),part=slice(node,start,mid);content.append(part);const ok=fits();part.remove();if(ok){best=mid;low=mid+1}else high=mid-1}if(best===start){if(content.children.length){page();continue}throw Error('Um bloco excede o espaço disponível.')}let end=best;if(best<text.length){const space=text.lastIndexOf(' ',best);if(space>start)end=space+1}const part=slice(node,start,end);content.append(part);const lineHeight=parseFloat(getComputedStyle(part).lineHeight)||22;if(end<text.length&&part.getBoundingClientRect().height<lineHeight*1.8&&content.children.length>1){part.remove();page();continue}if(end<text.length&&getComputedStyle(part).textAlign==='justify')part.style.textAlignLast='justify';start=end;if(start<text.length)page()}}
function putListItem(list){content.append(list);if(fits())return;list.remove();if(content.children.length)page();content.append(list);if(!fits()){list.remove();put(list.firstElementChild.cloneNode(true))}}
page();const source=document.getElementById('reportSource'),nodes=[];function collect(parent,inheritedAlign=''){let inline=null;for(const child of parent.childNodes){if(child.nodeType===3&&!child.textContent.trim())continue;if(child.nodeType===1&&child.matches('div,p')&&child.querySelector('p,div,h1,h2,h3,h4,h5,h6,ul,ol,blockquote')){inline=null;collect(child,child.style.textAlign||inheritedAlign)}else if(child.nodeType===1&&child.matches('p,div,h1,h2,h3,h4,h5,h6,ul,ol,blockquote')){inline=null;const clone=child.cloneNode(true);if(!clone.style.textAlign&&inheritedAlign)clone.style.textAlign=inheritedAlign;nodes.push(clone)}else{if(!inline){inline=document.createElement('p');if(inheritedAlign)inline.style.textAlign=inheritedAlign;nodes.push(inline)}inline.append(child.cloneNode(true))}}}
for(const n of source.children){if(n.id==='reportBodySource')collect(n);else nodes.push(n.cloneNode(true))}
for(let i=0;i<nodes.length;i++){const node=nodes[i];if(node.matches('h1,h2,h3,h4,h5,h6')&&nodes[i+1]&&content.children.length){const heading=node.cloneNode(true),probe=document.createElement('div');probe.style.height='12mm';content.append(heading,probe);const needsPage=!fits();heading.remove();probe.remove();if(needsPage)page()}put(node)}
Array.from(pages.children).forEach((p,i)=>p.querySelector('.report-page-number').textContent='Página '+(i+1)+' de '+pages.children.length);await Promise.all(Array.from(document.images).map(img=>img.decode()));document.getElementById('reportPrint').disabled=false;document.getElementById('reportPrintStatus').textContent=pages.children.length+' página(s). Imprima em A4, escala 100%, sem cabeçalhos e rodapés do navegador.';
}catch(e){document.getElementById('reportPrintStatus').textContent='Não foi possível preparar a impressão. Reabra a visualização. '+e.message}});
